  1	package hotel.web;
  2	
  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.databind.json.JsonMapper;
  6	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  7	import hotel.messages.SentMessages;
  8	import hotel.reports.OccupancyReport;
  9	import hotel.reports.RevenueReport;
 10	import hotel.reservations.ErrorCode;
 11	import hotel.reservations.Guest;
 12	import hotel.reservations.HotelException;
 13	import hotel.reservations.NewReservation;
 14	import hotel.reservations.ReservationService;
 15	import hotel.rooms.Rooms;
 16	import io.javalin.Javalin;
 17	import io.javalin.http.Context;
 18	import io.javalin.json.JavalinJackson;
 19	import java.time.LocalDate;
 20	import java.time.YearMonth;
 21	import java.time.format.DateTimeParseException;
 22	
 23	/** The HTTP API the inn's website and front desk call. */
 24	public final class HttpApi {
 25	
 26	    private final Javalin server;
 27	    private final Rooms rooms;
 28	    private final ReservationService reservations;
 29	    private final SentMessages sentMessages;
 30	    private final OccupancyReport occupancyReport;
 31	    private final RevenueReport revenueReport;
 32	
 33	    public HttpApi(
 34	            Rooms rooms,
 35	            ReservationService reservations,
 36	            SentMessages sentMessages,
 37	            OccupancyReport occupancyReport,
 38	            RevenueReport revenueReport) {
 39	        this.rooms = rooms;
 40	        this.reservations = reservations;
 41	        this.sentMessages = sentMessages;
 42	        this.occupancyReport = occupancyReport;
 43	        this.revenueReport = revenueReport;
 44	
 45	        ObjectMapper jsonMapper = JsonMapper.builder()
 46	                .addModule(new JavaTimeModule())
 47	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
 48	                .build();
 49	        this.server = Javalin.create(config -> {
 50	            config.showJavalinBanner = false;
 51	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
 52	        });
 53	        registerRoutes();
 54	        registerErrorHandling();
 55	    }
 56	
 57	    public Javalin server() {
 58	        return server;
 59	    }
 60	
 61	    private void registerRoutes() {
 62	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
 63	
 64	        server.post("/reservations", ctx -> {
 65	            NewReservation request = readNewReservation(ctx);
 66	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
 67	        });
 68	        server.get("/reservations/{id}", ctx ->
 69	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
 70	        server.post("/reservations/{id}/confirmation", ctx ->
 71	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
 72	        server.post("/reservations/{id}/cancellation", ctx ->
 73	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
 74	        server.post("/reservations/{id}/check-in", ctx ->
 75	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
 76	        server.post("/reservations/{id}/check-out", ctx ->
 77	                ctx.json(reservations.checkOut(reservationId(ctx))));
 78	        server.get("/reservations/{id}/document", ctx ->
 79	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
 80	
 81	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
 82	
 83	        server.get("/reports/occupancy", ctx -> {
 84	            LocalDate night = readDate(ctx);
 85	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
 86	        });
 87	        server.get("/reports/revenue", ctx -> {
 88	            YearMonth month = readMonth(ctx);
 89	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
 90	        });
 91	    }
 92	
 93	    private void registerErrorHandling() {
 94	        server.exception(HotelException.class, (exception, ctx) -> {
 95	            ctx.status(httpStatus(exception.errorCode()));
 96	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
 97	        });
 98	    }
 99	
100	    private static int httpStatus(ErrorCode errorCode) {
101	        return switch (errorCode) {
102	            case INVALID_REQUEST -> 400;
103	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
104	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
105	            case CAPACITY_EXCEEDED -> 422;
106	        };
107	    }
108	
109	    private static NewReservation readNewReservation(Context ctx) {
110	        CreateReservationRequest body;
111	        try {
112	            body = ctx.bodyAsClass(CreateReservationRequest.class);
113	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
114	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
115	        }
116	        if (body == null
117	                || body.roomNumber() == null
118	                || isBlank(body.guestName())
119	                || isBlank(body.guestEmail())
120	                || body.checkIn() == null
121	                || body.checkOut() == null
122	                || body.guests() == null
123	                || body.ratePlan() == null) {
124	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
125	        }
126	
127	        // Validate that exactly one type of identification is provided
128	        boolean hasCpf = !isBlank(body.guestCpf());
129	        boolean hasCompany = !isBlank(body.companyCnpj()) || !isBlank(body.companyName());
130	        boolean hasPassport = !isBlank(body.guestPassport()) || !isBlank(body.guestCountry());
131	
132	        int identificationCount = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);
133	        if (identificationCount != 1) {
134	            throw new HotelException(ErrorCode.INVALID_REQUEST,
135	                    "provide either guestCpf, or companyCnpj with companyName, or guestPassport with guestCountry");
136	        }
137	
138	        // Validate completeness of each identification type
139	        if (hasCompany && (isBlank(body.companyCnpj()) || isBlank(body.companyName()))) {
140	            throw new HotelException(ErrorCode.INVALID_REQUEST,
141	                    "both companyCnpj and companyName are required together");
142	        }
143	        if (hasPassport && (isBlank(body.guestPassport()) || isBlank(body.guestCountry()))) {
144	            throw new HotelException(ErrorCode.INVALID_REQUEST,
145	                    "both guestPassport and guestCountry are required together");
146	        }
147	
148	        Guest guest = new Guest(
149	                body.guestName(),
150	                body.guestEmail(),
151	                body.guestCpf(),
152	                body.companyCnpj(),
153	                body.companyName(),
154	                body.guestPassport(),
155	                body.guestCountry());
156	        return new NewReservation(
157	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
158	    }
159	
160	    private static long reservationId(Context ctx) {
161	        String id = ctx.pathParam("id");
162	        try {
163	            return Long.parseLong(id);
164	        } catch (NumberFormatException notANumber) {
165	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
166	        }
167	    }
168	
169	    private static LocalDate readDate(Context ctx) {
170	        String date = requiredQueryParam(ctx, "date");
171	        try {
172	            return LocalDate.parse(date);
173	        } catch (DateTimeParseException badDate) {
174	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
175	        }
176	    }
177	
178	    private static YearMonth readMonth(Context ctx) {
179	        String month = requiredQueryParam(ctx, "month");
180	        try {
181	            return YearMonth.parse(month);
182	        } catch (DateTimeParseException badMonth) {
183	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
184	        }
185	    }
186	
187	    private static String requiredQueryParam(Context ctx, String name) {
188	        String value = ctx.queryParam(name);
189	        if (value == null) {
190	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
191	        }
192	        return value;
193	    }
194	
195	    private static boolean isBlank(String text) {
196	        return text == null || text.isBlank();
197	    }
198	}
  1	package hotel.reservations;
  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.rooms.Room;
  6	import hotel.rooms.Rooms;
  7	import java.math.BigDecimal;
  8	
  9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 10	public final class ReservationService {
 11	
 12	    static final String HOTEL_NAME = "Pousada Maré Alta";
 13	
 14	    private final Rooms rooms;
 15	    private final ReservationStore store;
 16	    private final PriceCalculator priceCalculator;
 17	    private final EmailSender emailSender;
 18	
 19	    public ReservationService(
 20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 21	        this.rooms = rooms;
 22	        this.store = store;
 23	        this.priceCalculator = priceCalculator;
 24	        this.emailSender = emailSender;
 25	    }
 26	
 27	    public synchronized Reservation create(NewReservation request) {
 28	        if (!request.checkOut().isAfter(request.checkIn())) {
 29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 30	        }
 31	        if (request.guests() < 1) {
 32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 33	        }
 34	        Room room = rooms.find(request.roomNumber())
 35	                .orElseThrow(() -> new HotelException(
 36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 37	        if (request.guests() > room.capacity()) {
 38	            throw new HotelException(
 39	                    ErrorCode.CAPACITY_EXCEEDED,
 40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 41	        }
 42	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 43	            throw new HotelException(
 44	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 45	        }
 46	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 47	        return store.add(request, price);
 48	    }
 49	
 50	    public Reservation find(long reservationId) {
 51	        return store.find(reservationId)
 52	                .orElseThrow(() -> new HotelException(
 53	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 54	    }
 55	
 56	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 57	    public synchronized Reservation confirm(long reservationId) {
 58	        Reservation reservation = find(reservationId);
 59	        if (reservation.status() != ReservationStatus.PENDING) {
 60	            throw notAllowed(reservation, "confirm");
 61	        }
 62	        reservation.confirmPayment();
 63	        store.update(reservation);
 64	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 65	        emailSender.send(
 66	                reservation.guest().email(),
 67	                "Reserva confirmada - " + HOTEL_NAME,
 68	                confirmationEmailBody(reservation, receipt));
 69	        return reservation;
 70	    }
 71	
 72	    /**
 73	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 74	     * reservation was never paid, so nothing comes back).
 75	     */
 76	    public synchronized Reservation cancel(long reservationId) {
 77	        Reservation reservation = find(reservationId);
 78	        if (reservation.status() != ReservationStatus.PENDING
 79	                && reservation.status() != ReservationStatus.CONFIRMED) {
 80	            throw notAllowed(reservation, "cancel");
 81	        }
 82	        BigDecimal refund = switch (reservation.ratePlan()) {
 83	            case STANDARD -> reservation.amountPaid();
 84	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 85	        };
 86	        reservation.cancel(refund);
 87	        store.update(reservation);
 88	        return reservation;
 89	    }
 90	
 91	    public synchronized Reservation checkIn(long reservationId) {
 92	        Reservation reservation = find(reservationId);
 93	        if (reservation.status() != ReservationStatus.CONFIRMED) {
 94	            throw notAllowed(reservation, "check in");
 95	        }
 96	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
 97	        store.update(reservation);
 98	        return reservation;
 99	    }
100	
101	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
102	    public synchronized ReservationReceipt checkOut(long reservationId) {
103	        Reservation reservation = find(reservationId);
104	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
105	            throw notAllowed(reservation, "check out");
106	        }
107	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
108	        store.update(reservation);
109	        return new ReservationReceipt(reservation, roomOf(reservation));
110	    }
111	
112	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
113	    public ReservationReceipt receiptCopy(long reservationId) {
114	        Reservation reservation = find(reservationId);
115	        if (!reservation.isPaid()) {
116	            throw notAllowed(reservation, "issue a receipt for");
117	        }
118	        return new ReservationReceipt(reservation, roomOf(reservation));
119	    }
120	
121	    private Room roomOf(Reservation reservation) {
122	        return rooms.find(reservation.roomNumber()).orElseThrow();
123	    }
124	
125	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
126	        return "Olá, " + reservation.guest().name() + "!\n\n"
127	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
128	                + receipt.text() + "\n"
129	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
130	                + "Até breve!\n";
131	    }
132	
133	    private static HotelException notAllowed(Reservation reservation, String operation) {
134	        return new HotelException(
135	                ErrorCode.OPERATION_NOT_ALLOWED,
136	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
137	    }
138	}

