160	    private static long reservationId(Context ctx) {
161	        String id = ctx.pathParam("id");
162	        try {
163	            return Long.parseLong(id);
164	        } catch (NumberFormatException notANumber) {
165	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
166	        }
167	    }
168	
169	    private static LocalDate readDate(Context ctx) {
170	        String date = requiredQueryParam(ctx, "date");
171	        try {
172	            return LocalDate.parse(date);
173	        } catch (DateTimeParseException badDate) {
174	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
175	        }
176	    }
177	
178	    private static YearMonth readMonth(Context ctx) {
179	        String month = requiredQueryParam(ctx, "month");
180	        try {
181	            return YearMonth.parse(month);
182	        } catch (DateTimeParseException badMonth) {
183	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
184	        }
185	    }
186	
187	    private static String requiredQueryParam(Context ctx, String name) {
188	        String value = ctx.queryParam(name);
189	        if (value == null) {
190	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
191	        }
192	        return value;
193	    }
194	
195	    private static boolean isBlank(String text) {
196	        return text == null || text.isBlank();
197	    }
